  "terminology": [
    {
      "term": "Cold War",
      "definition": "A state of extreme geopolitical hostility and ideological rivalry between the US and USSR (1945–1991) characterized by proxy wars, espionage, and nuclear arms race without direct military conflict."
    },
    {
      "term": "Capitalism",
      "definition": "An economic and political system based on private ownership of industry, free-market competition, profit motive, and multi-party democratic government."
    },
    {
      "term": "Communism",
      "definition": "A Marxist-Leninist system based on state ownership of all industry and land, elimination of private property, wealth redistribution, and single-party authoritarian rule."
    },
    {
      "term": "Containment",
      "definition": "The core US foreign policy doctrine formulated by George Kennan in 1946 aimed at blocking the global spread of Soviet communist influence through economic and military aid."
    },
    {
      "term": "Truman Doctrine",
      "definition": "President Truman’s March 1947 declaration pledging American military and financial assistance to any nation resisting subjugation by armed communist minorities or outside pressure."
    },
    {
      "term": "Marshall Plan",
      "definition": "A massive US economic aid initiative (1948–1952) providing $13 billion to rebuild war-torn Western European economies, successfully containing communist electoral appeals."
    },
    {
      "term": "Iron Curtain",
      "definition": "Metaphor coined by Winston Churchill in 1946 describing the physical and ideological barrier separating democratic Western Europe from Soviet-dominated Eastern Europe."
    },
    {
      "term": "Berlin Airlift",
      "definition": "Western Allied operation (1948–49) flying 2.3 million tons of supplies to 2.5 million West Berliners over eleven months, defeating Stalin’s illegal land blockade."
    },
    {
      "term": "NATO",
      "definition": "North Atlantic Treaty Organization; military alliance established in April 1949 where Western democratic nations pledged mutual military defense against Soviet aggression."
    },
    {
      "term": "Warsaw Pact",
      "definition": "A military mutual defense treaty established in 1955 by the Soviet Union and seven Eastern European satellite states in response to West Germany joining NATO."
    },
    {
      "term": "Brinkmanship",
      "definition": "The practice of pushing dangerous geopolitical disputes to the very verge of active nuclear war in order to compel the opposing superpower to back down."
    },
    {
      "term": "Mutually Assured Destruction (MAD)",
      "definition": "Military doctrine holding that because both superpowers possessed survivable second-strike nuclear arsenals, any nuclear exchange would result in total mutual annihilation."
    },
    {
      "term": "Proxy War",
      "definition": "A regional armed conflict where opposing superpowers support, fund, and arm rival local factions instead of engaging in direct military combat with each other."
    },
    {
      "term": "Domino Theory",
      "definition": "The geopolitical theory that if one nation fell to communism, neighbouring countries would inevitably collapse like a row of falling dominoes."
    },
    {
      "term": "Détente",
      "definition": "The period of easing geopolitical tensions and diplomatic cooperation between the US and USSR during the 1970s, resulting in the SALT I arms limitation treaties."
    },
    {
      "term": "Glasnost",
      "definition": "Mikhail Gorbachev’s policy of \"openness\" introduced in 1985, allowing freedom of the press, public debate, and criticism of historical Soviet state corruption."
    },
    {
      "term": "Perestroika",
      "definition": "Gorbachev’s policy of \"restructuring\" aimed at decentralizing Soviet economic control, introducing limited private enterprise and market efficiency."
    },
    {
      "term": "Brezhnev Doctrine",
      "definition": "Soviet policy declared in 1968 stating that Moscow had the right to intervene militarily in any communist state where socialist rule was threatened; renounced by Gorbachev in 1989."
    }
  ],
